Deno.test({
  name: "domains model: list_domains walks every page of a list",
  sanitizeResources: false,
  fn: async () => {
    const { url, server, requests } = startMockServer({
      "GET /1010/domains": (url: URL) =>
        url.searchParams.get("page") === "2"
          ? {
            body: {
              "data": [{
                "id": 1,
                "account_id": 1,
                "registrant_id": 1,
                "name": "test-value",
                "unicode_name": "test-value",
                "state": "hosted",
                "auto_renew": true,
                "private_whois": true,
                "expires_at": "2024-01-01T00:00:00Z",
                "trustee": true,
                "expires_on": "2010-01-01",
                "created_at": "2010-01-01T01:00:00Z",
                "updated_at": "2010-01-01T01:00:00Z",
              }],
              "pagination": {
                "current_page": 2,
                "per_page": 100,
                "total_entries": 2,
                "total_pages": 2,
              },
            },
          }
          : {
            body: {
              "data": [{
                "id": 1,
                "account_id": 1,
                "registrant_id": 1,
                "name": "test-value",
                "unicode_name": "test-value",
                "state": "hosted",
                "auto_renew": true,
                "private_whois": true,
                "expires_at": "2024-01-01T00:00:00Z",
                "trustee": true,
                "expires_on": "2010-01-01",
                "created_at": "2010-01-01T01:00:00Z",
                "updated_at": "2010-01-01T01:00:00Z",
              }],
              "pagination": {
                "current_page": 1,
                "per_page": 100,
                "total_entries": 2,
                "total_pages": 2,
              },
            },
          },
    });
    const uninstall = installFetchMock(url);

    try {
      const { context, getWrittenResources } = newContext();
      await run("list_domains", { "sort": "id:asc" }, context);
      assertEquals(requests.map((r) => r.url.searchParams.get("page")), [
        "1",
        "2",
      ]);
      assertEquals(
        requests.every((r) => r.url.searchParams.get("per_page") === "100"),
        true,
      );
      const resources = getWrittenResources();
      assertEquals(resources.length, 1);
      const data = resources[0].data as {
        items: unknown[];
        truncated: boolean;
      };
      assertEquals(data.items.length, 2);
      assertEquals(data.truncated, false);
    } finally {
      uninstall();
      await server.shutdown();
    }
  },
});

